STRFTIME(
    CASE
        WHEN make_date(
            year(current_date),
            month(CAST("head_accounts_StartDate" AS TIMESTAMP)),
            least(
                day(CAST("head_accounts_StartDate" AS TIMESTAMP)),
                day(
                    last_day(
                        make_date(
                            year(current_date),
                            month(CAST("head_accounts_StartDate" AS TIMESTAMP)),
                            1
                        )
                    )
                )
            )
        ) < current_date + INTERVAL 60 DAY

        THEN make_date(
            year(current_date) + 1,
            month(CAST("head_accounts_StartDate" AS TIMESTAMP)),
            least(
                day(CAST("head_accounts_StartDate" AS TIMESTAMP)),
                day(
                    last_day(
                        make_date(
                            year(current_date) + 1,
                            month(CAST("head_accounts_StartDate" AS TIMESTAMP)),
                            1
                        )
                    )
                )
            )
        )

        ELSE make_date(
            year(current_date),
            month(CAST("head_accounts_StartDate" AS TIMESTAMP)),
            least(
                day(CAST("head_accounts_StartDate" AS TIMESTAMP)),
                day(
                    last_day(
                        make_date(
                            year(current_date),
                            month(CAST("head_accounts_StartDate" AS TIMESTAMP)),
                            1
                        )
                    )
                )
            )
        )
    END,
    '%Y-%m-%d'
)
